package com.eudistack.ebw.domain.model;

import java.security.MessageDigest;
import java.time.Instant;
import java.util.Arrays;
import java.util.Objects;
import java.util.UUID;

/**
 * Wallet account. One per email and tenant; its Wallet Unit is 1:1 with it.
 *
 * <p>{@code webauthnUserHandle} is the WebAuthn user handle of the account's passkeys:
 * 32 random bytes generated by the service, never derived from the email.
 */
public class WalletUser {

    public static final int USER_HANDLE_LENGTH = 32;

    private UUID id;
    private String email;
    private byte[] webauthnUserHandle;
    private Instant createdAt;
    private Instant updatedAt;

    public WalletUser(UUID id, String email, byte[] webauthnUserHandle, Instant createdAt, Instant updatedAt) {
        this.id = id;
        this.email = email;
        this.webauthnUserHandle = webauthnUserHandle;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    public static WalletUser create(String email, byte[] webauthnUserHandle) {
        Objects.requireNonNull(webauthnUserHandle, "webauthnUserHandle");
        if (webauthnUserHandle.length != USER_HANDLE_LENGTH) {
            throw new IllegalArgumentException("WebAuthn user handle must be " + USER_HANDLE_LENGTH + " bytes");
        }
        var now = Instant.now();
        return new WalletUser(UUID.randomUUID(), email, webauthnUserHandle.clone(), now, now);
    }

    /** Constant-time comparison with the user handle returned by an authenticator. */
    public boolean hasUserHandle(byte[] candidate) {
        return candidate != null && webauthnUserHandle != null
                && MessageDigest.isEqual(webauthnUserHandle, candidate);
    }

    public UUID getId() { return id; }
    public String getEmail() { return email; }
    public byte[] getWebauthnUserHandle() {
        return webauthnUserHandle == null ? null : Arrays.copyOf(webauthnUserHandle, webauthnUserHandle.length);
    }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }

    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
}
